window.AUTH=window.AUTH||{};window.AUTH["98-1949"]={"d":"98-1949","id":"1999/98-1949","n":"Pegram v. Herdrich","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting petitioners","date":"","url":"https://www.justice.gov/osg/media/225971/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/pegram-v-herdrich-amicus-merits","n":62}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep530/usrep530211/usrep530211.pdf","tr":false,"items":[{"t":"case","label":"Alessi v. Raybestos-Manhattan, Inc.","cite":"451 U.S. 504","y":1981,"id":"1980/79-1943","sc":1,"sum":"In two suits initiated in New Jersey state court, retired employees who had received workers' compensation awards subsequent to retirement challenged the validity of provisions in their employers' pension plans reducing a retiree's pension benefits by an amount equal to a workers' compensation award for which the retiree is eligible. These private pension plans are subject to federal regulation under the Employee …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Anderson v. Humana, Inc.","cite":"24 F.3d 889","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/24/889/","by":{"0":"12"}},{"t":"case","label":"Bailey v. Blue Cross & Blue Shield of Virginia","cite":"67 F.3d 53","y":1995,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/67/53/","by":{"0":"22"}},{"t":"case","label":"Boggs v. Boggs","cite":"520 U.S. 833","y":1997,"id":"1996/96-79","sc":1,"sum":"The Court ruled that the Employee Retirement Income Security Act of 1974 (ERISA) preempts state community-property law allowing a non-participant spouse to transfer by a testamentary instrument an interest in undistributed pension plan benefits.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Cannon v. Group Health Serv., Inc.","cite":"77 F.3d 1270","y":1996,"url":"https://www.courtlistener.com/c/F.3d/77/1270/","by":{"0":"22"}},{"t":"case","label":"Conley v. Gibson","cite":"355 U.S. 41","y":1957,"id":"1957/7","sc":1,"sum":"Petitioners, who are Negro members of a union designated as their bargaining agent under the Railway Labor Act, brought a class suit against the union, its brotherhood and certain of their officers to compel them to represent petitioners without discrimination in protection of their employment and seniority rights under a contract between the union and the Railroad. They alleged that the Railroad had purported to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"De Buono v. NYSA-ILA Med. & Clinical Servs. Fund","cite":"520 U.S. 806","y":1997,"id":"1996/95-1594","sc":1,"sum":"Authored by Justice John Paul Stevens, the Court ruled that the Employee Retirement Income Security Act does not preclude New York from imposing a gross receipts tax on ERISA funded medical centers.","sumSrc":"Oyez","by":{"0":"13-14, 17"}},{"t":"case","label":"Donovan v. Bierwirth","cite":"680 F.2d 263","y":1982,"url":"https://www.courtlistener.com/c/F.2d/680/263/","op":1,"by":{"0":"5, 28-29"}},{"t":"case","label":"Donovan v. Dillingham","cite":"688 F.2d 1367","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/688/1367/","by":{"0":"10"}},{"t":"case","label":"Doyle v. Paul Revere Life Ins., Co.","cite":"144 F.3d 181","y":1998,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/144/181/","by":{"0":"28"}},{"t":"case","label":"Dukes v. U.S. Healthcare, Inc.","cite":"57 F.3d 350","y":1995,"url":"https://www.courtlistener.com/c/F.3d/57/350/","op":1,"by":{"0":"11, 14, 17"}},{"t":"case","label":"Englehardt v. Paul Revere Life Ins. Co.","cite":"139 F.3d 1346","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/139/1346/","by":{"0":"22"}},{"t":"case","label":"Firestone Tire & Rubber Co. v. Bruch","cite":"489 U.S. 101","y":1989,"id":"1988/87-1054","sc":1,"sum":"Petitioner Firestone Tire & Rubber Co. (Firestone) maintained, and was the plan administrator and fiduciary of, a termination pay plan and two other unfunded employee benefit plans governed by the Employee Retirement Income Security Act of 1974 (ERISA), 29 U. S. C. § 1001 et seq. After Firestone sold its Plastics Division to Occidental Petroleum Co. (Occidental), respondents, Plastics Division employees who were …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 28"}},{"t":"case","label":"Fort Halifax Packing Co. v. Coyne","cite":"482 U.S. 1","y":1987,"id":"1986/86-341","sc":1,"sum":"After appellant closed its poultry packaging and processing plant and laid off most of the employees who worked there, the Director of Maine's Bureau of Labor Standards filed suit to enforce the provisions of a state statute requiring employers, in the event of a plant closing, to provide a one-time severance payment to employees not covered by an express contract providing for severance pay. The State Superior …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 15"}},{"t":"case","label":"Grimo v. Blue Cross/Blue Shield","cite":"34 F.3d 148","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/34/148/","by":{"0":"10"}},{"t":"case","label":"Group Life & Health Ins. Co. v. Royal Drug Co.","cite":"440 U.S. 205","y":1979,"id":"1978/77-952","sc":1,"sum":"The Pharmacy Agreements are not the \"business of insurance\" within the meaning of § 2 (b).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Hughes Aircraft Co. v. Jacobson","cite":"119 S. Ct. 755","y":1999,"id":"1998/97-1287","sc":1,"op":1,"sum":"The Court held Hughes did not violate the ERISA by establishing an early retirement program and creating a noncontributory benefit structure for new participants. Justice Thomas, writing for the Court, said the plan amendments \"did not affect the rights of pre-existing plan participants and Hughes did not use the surplus for its own benefit.\".","sumSrc":"Oyez","by":{"0":"1, 15"}},{"t":"case","label":"Ingersoll-Rand Co. v. McClendon","cite":"498 U.S. 133","y":1990,"id":"1990/89-1298","sc":1,"sum":"ERISA's explicit language and its structure and purpose demonstrate a congressional intent to pre-empt a state common law claim that an employee was unlawfully discharged to prevent his attainment of benefits under an ERISA-covered plan.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Kenney v. Roland Parson Contracting Corp.","cite":"28 F.3d 1254","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/28/1254/","by":{"0":"10"}},{"t":"case","label":"Kuhl v. Lincoln Nat’l Health Plan, Inc.","cite":"999 F.2d 298","y":1993,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/999/298/","by":{"0":"22"}},{"t":"case","label":"Libbey-Owens-Ford Co. v. Blue Cross & Blue Shield Mut. of Ohio","cite":"982 F.2d 1031","y":1993,"url":"https://www.courtlistener.com/c/F.2d/982/1031/","by":{"0":"22"}},{"t":"case","label":"Lockheed Corp. v. Spink","cite":"517 U.S. 882","y":1996,"id":"1995/95-809","sc":1,"op":1,"sum":"In unanimous and 7-2 decisions, announced by Justice Clarence Thomas, the Court ruled that businesses may condition early retirement benefits on the forfeiture of the right to sue in a job-related claim. The Court also ruled that the government could not retroactively apply retirement income benefit laws.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Lordmann Enters., Inc. v. Equicor, Inc.","cite":"32 F.3d 1529","y":1994,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/32/1529/","by":{"0":"16"}},{"t":"case","label":"Lupo v. Human Affairs Int’l Inc.","cite":"28 F.3d 269","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/28/269/","by":{"0":"14"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1, 11"}},{"t":"case","label":"New York State Conference of Blue Cross & Blue Shield Plans v. Travelers Ins. Co.","cite":"514 U.S. 645","y":1995,"id":"1994/93-1408","sc":1,"op":1,"sum":"New York's surcharge provisions do not \"relate to\" employee benefit plans within the meaning of § 514(a) and, thus, are not pre-empted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 14, 21"}},{"t":"case","label":"Pacificare of Okla., Inc. v. Burrage","cite":"59 F.3d 151","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/59/151/","by":{"0":"13"}},{"t":"case","label":"Parrino v. FHP, Inc.","cite":"146 F.3d 699","y":1998,"url":"https://www.courtlistener.com/c/F.3d/146/699/","by":{"0":"22"}},{"t":"case","label":"Pilot Life Ins. Co. v. Dedeaux","cite":"481 U.S. 41","y":1987,"id":"1986/85-1043","sc":1,"sum":"ERISA pre-empts respondent's suit under state common law for alleged improper processing of his claim for benefits under the ERISAregulated benefit plan.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Rice v. Panchal","cite":"65 F.3d 637","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/65/637/","by":{"0":"14"}},{"t":"case","label":"Texas Pharmacy Ass’n v. Prudential Ins. Co.","cite":"105 F.3d 1035","y":1997,"url":"https://www.courtlistener.com/c/F.3d/105/1035/","op":1,"by":{"0":"12"}},{"t":"case","label":"Tregoning v. American Community Mut. Ins. Co.","cite":"12 F.3d 79","y":1993,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/12/79/","by":{"0":"22"}},{"t":"case","label":"Turner v. Fallon Community Health Plan","cite":"127 F.3d 196","y":1997,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/127/196/","by":{"0":"22"}},{"t":"case","label":"UNUM Life Ins. Co. v. Ward","cite":"119 S. Ct. 1380","y":1999,"id":"1998/97-1868","sc":1,"sum":"Delivered by Justice Ruth Bader Ginsburg, the Court held that California's agency rule is preempted by the Employee Retirement Income Security Act of 1974. Justice Ginsburg wrote for the Court that California's common-law agency rule \"would have a marked effect on plan administration,\" adding that it would force employers to take on a role for which they had not volunteered.","sumSrc":"Oyez","by":{"0":"21, 22"}},{"t":"case","label":"Varity Corp. v. Howe","cite":"516 U.S. 489","y":1996,"id":"1995/94-1471","sc":1,"op":2,"sum":"Holding that ERISA fiduciaries may have duties to disclose information about plan prospects that they have no duty, or even power, to change.","sumSrc":"opinion","by":{"0":"1, 11, 14, 15"}},{"t":"case","label":"Washington Physicians Serv. Ass’n v. Gregoire","cite":"147 F.3d 1039","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/147/1039/","op":2,"by":{"0":"12"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"1, 7, 10"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(1)","(13)","(21)(A)"],"stext":{"head":"§1002. Definitions","paras":[[0,"For purposes of this subchapter:"],[0,"(1) The terms \"employee welfare benefit plan\" and \"welfare plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that such plan, fund, or program was established or is maintained for the purpose of providing for its participants or their beneficiaries, through the purchase of insurance or otherwise, (A) medical, surgical, or hospital care or benefits, or benefits in the event of sickness, accident, disability, death or unemployment, or vacation benefits, apprenticeship or other training programs, or day care centers, scholarship funds, or prepaid legal services, or (B) any benefit described in section 186(c) of this title (other than pensions on retirement or death, and insurance to provide such pensions)."],[0,"(2)(A) Except as provided in subparagraph (B), the terms \"employee pension benefit plan\" and \"pension plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that by its express terms or as a result of surrounding circumstances such plan, fund, or program—"],[1,"(i) provides retirement income to employees, or"],[1,"(ii) results in a deferral of income by employees for periods extending to the termination of covered employment or beyond,"],[0,"regardless of the method of calculating the contributions made to the plan, the method of calculating the benefits under the plan or the method of distributing benefits from the plan. A distribution from a plan, fund, or program shall not be treated as made in a form other than retirement income or as a distribution prior to termination of covered employment solely because such distribution is made to an employee who has attained age 62 and who is not separated from employment at the time of such distribution."],[0,"(B) The Secretary may by regulation prescribe rules consistent with the standards and purposes of this chapter providing one or more exempt categories under which—"],[1,"(i) severance pay arrangements, and"],[1,"(ii) supplemental retirement income payments, under which the pension benefits of retirees or their beneficiaries are supplemented to take into account some portion or all of the increases in the cost of living (as determined by the Secretary of Labor) since retirement,"],[0,"shall, for purposes of this subchapter, be treated as welfare plans rather than pension plans. In the case of any arrangement or payment a principal effect of which is the evasion of the standards or purposes of this chapter applicable to pension plans, such arrangement or payment shall be treated as a pension plan. An applicable voluntary early retirement incentive plan (as defined in section 457(e)(11)(D)(ii) of title 26) making payments or supplements described in section 457(e)(11)(D)(i) of title 26, and an applicable employment retention plan (as defined in section 457(f)(4)(C) of title 26) making payments of benefits described in section 457(f)(4)(A) of title 26, shall, for purposes of this subchapter, be treated as a welfare plan (and not a pension plan) with respect to such payments and supplements."],[0,"(C) A pooled employer plan shall be treated as—"],[1,"(i) a single employee pension benefit plan or single pension plan; and"],[1,"(ii) a plan to which section 1060(a) of this title applies."],[0,"(3) The term \"employee benefit plan\" or \"plan\" means an employee welfare benefit plan or an employee pension benefit plan or a plan which is both an employee welfare benefit plan and an employee pension benefit plan."],[0,"(4) The term \"employee organization\" means any labor union or any organization of any kind, or any agency or employee representation committee, association, group, or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning an employee benefit plan, or other matters incidental to employment relationships; or any employees' beneficiary association organized for the purpose in whole or in part, of establishing such a plan."],[0,"(5) The term \"employer\" means any person acting directly as an employer, or indirectly in the interest of an employer, in relation to an employee benefit plan; and includes a group or association of employers acting for an employer in such capacity."],[0,"(6) The term \"employee\" means any individual employed by an employer."],[0,"(7) The term \"participant\" means any employee or former employee of an employer, or any member or former member of an employee organization, who is or may become eligible to receive a benefit of any type from an employee benefit plan which covers employees of such employer or members of such organization, or whose beneficiaries may be eligible to receive any such benefit."],[0,"(8) The term \"beneficiary\" means a person designated by a participant, or by the terms of an employee benefit plan, who is or may become entitled to a benefit thereunder."],[0,"(9) The term \"person\" means an individual, partnership, joint venture, corporation, mutual company, joint-stock company, trust, estate, unincorporated organization, association, or employee organization."],[0,"(10) The term \"State\" includes any State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, and the Canal Zone. The term \"United States\" when used in the geographic sense means the States and the Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act (43 U.S.C. 1331–1343)."],[0,"(11) The term \"commerce\" means trade, traffic, commerce, transportation, or communication between any State and any place outside thereof."],[0,"(12) The term \"industry or activity affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce, and includes any activity or industry \"affecting commerce\" within the meaning of the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], or the Railway Labor Act [45 U.S.C. 151 et seq.]."],[0,"(13) The term \"Secretary\" means the Secretary of Labor."],[0,"(14) The term \"party in interest\" means, as to an employee benefit plan—"],[1,"(A) any fiduciary (including, but not limited to, any administrator, officer, trustee, or custodian), counsel, or employee of such employee benefit plan;"],[1,"(B) a person providing services to such plan;"],[1,"(C) an employer any of whose employees are covered by such plan;"],[1,"(D) an employee organization any of whose members are covered by such plan;"],[1,"(E) an owner, direct or indirect, of 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of a corporation.1"],[2,"(ii) the capital interest or the profits interest of a partnership, or"],[2,"(iii) the beneficial interest of a trust or unincorporated enterprise,"],[1,"which is an employer or an employee organization described in subparagraph (C) or (D);"],[1,"(F) a relative (as defined in paragraph (15)) of any individual described in subparagraph (A), (B), (C), or (E);"],[1,"(G) a corporation, partnership, or trust or estate of which (or in which) 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of such corporation,"],[2,"(ii) the capital interest or profits interest of such partnership, or"],[2,"(iii) the beneficial interest of such trust or estate,"],[1,"is owned directly or indirectly, or held by persons described in subparagraph (A), (B), (C), (D), or (E);"],[1,"(H) an employee, officer, director (or an individual having powers or responsibilities similar to those of officers or directors), or a 10 percent or more shareholder directly or indirectly, of a person described in subparagraph (B), (C), (D), (E), or (G), or of the employee benefit plan; or"],[1,"(I) a 10 percent or more (directly or indirectly in capital or profits) partner or joint venturer of a person described in subparagraph (B), (C), (D), (E), or (G)."],[0,"The Secretary, after consultation and coordination with the Secretary of the Treasury, may by regulation prescribe a percentage lower than 50 percent for subparagraph (E) and (G) and lower than 10 percent for subparagraph (H) or (I). The Secretary may prescribe regulations for determining the ownership (direct or indirect) of profits and beneficial interests, and the manner in which indirect stockholdings are taken into account. Any person who is a party in interest with respect to a plan to which a trust described in section 501(c)(22) of title 26 is permitted to make payments under section 1403 of this title shall be treated as a party in interest with respect to such trust."],[0,"(15) The term \"relative\" means a spouse, ancestor, lineal descendant, or spouse of a lineal descendant."],[0,"(16)(A) The term \"administrator\" means—"],[1,"(i) the person specifically so designated by the terms of the instrument under which the plan is operated;"],[1,"(ii) if an administrator is not so designated, the plan sponsor; or"],[1,"(iii) in the case of a plan for which an administrator is not designated and a plan sponsor cannot be identified, such other person as the Secretary may by regulation prescribe."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1002?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1002. Definitions","tname":"Labor","by":{"0":"10, 12, 15, 12, 15"}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)(1)","(a)(1)(A)","(a)(1)(A)(i)"],"stext":{"head":"§1104. Fiduciary duties","paras":[[0,"(a) Prudent man standard of care"],[0,"(1) Subject to sections 1103(c) and (d), 1342, and 1344 of this title, a fiduciary shall discharge his duties with respect to a plan solely in the interest of the participants and beneficiaries and—"],[1,"(A) for the exclusive purpose of:"],[2,"(i) providing benefits to participants and their beneficiaries; and"],[2,"(ii) defraying reasonable expenses of administering the plan;"],[1,"(B) with the care, skill, prudence, and diligence under the circumstances then prevailing that a prudent man acting in a like capacity and familiar with such matters would use in the conduct of an enterprise of a like character and with like aims;"],[1,"(C) by diversifying the investments of the plan so as to minimize the risk of large losses, unless under the circumstances it is clearly prudent not to do so; and"],[1,"(D) in accordance with the documents and instruments governing the plan insofar as such documents and instruments are consistent with the provisions of this subchapter and subchapter III."],[0,"(2) In the case of an eligible individual account plan (as defined in section 1107(d)(3) of this title), the diversification requirement of paragraph (1)(C) and the prudence requirement (only to the extent that it requires diversification) of paragraph (1)(B) is not violated by acquisition or holding of qualifying employer real property or qualifying employer securities (as defined in section 1107(d)(4) and (5) of this title)."],[0,"(b) Indicia of ownership of assets outside jurisdiction of district courts"],[0,"Except as authorized by the Secretary by regulations, no fiduciary may maintain the indicia of ownership of any assets of a plan outside the jurisdiction of the district courts of the United States."],[0,"(c) Control over assets by participant or beneficiary"],[0,"(1)(A) In the case of a pension plan which provides for individual accounts and permits a participant or beneficiary to exercise control over the assets in his account, if a participant or beneficiary exercises control over the assets in his account (as determined under regulations of the Secretary)—"],[1,"(i) such participant or beneficiary shall not be deemed to be a fiduciary by reason of such exercise, and"],[1,"(ii) no person who is otherwise a fiduciary shall be liable under this part for any loss, or by reason of any breach, which results from such participant's or beneficiary's exercise of control, except that this clause shall not apply in connection with such participant or beneficiary for any blackout period during which the ability of such participant or beneficiary to direct the investment of the assets in his or her account is suspended by a plan sponsor or fiduciary."],[0,"(B) If a person referred to in subparagraph (A)(ii) meets the requirements of this subchapter in connection with authorizing and implementing the blackout period, any person who is otherwise a fiduciary shall not be liable under this subchapter for any loss occurring during such period."],[0,"(C) For purposes of this paragraph, the term \"blackout period\" has the meaning given such term by section 1021(i)(7) of this title."],[0,"(2) In the case of a simple retirement account established pursuant to a qualified salary reduction arrangement under section 408(p) of title 26, a participant or beneficiary shall, for purposes of paragraph (1), be treated as exercising control over the assets in the account upon the earliest of—"],[1,"(A) an affirmative election among investment options with respect to the initial investment of any contribution,"],[1,"(B) a rollover to any other simple retirement account or individual retirement plan, or"],[1,"(C) one year after the simple retirement account is established."],[0,"No reports, other than those required under section 1021(g) of this title, shall be required with respect to a simple retirement account established pursuant to such a qualified salary reduction arrangement."],[0,"(3) In the case of a pension plan which makes a transfer to an individual retirement account or annuity of a designated trustee or issuer under section 401(a)(31)(B) of title 26, the participant or beneficiary shall, for purposes of paragraph (1), be treated as exercising control over the assets in the account or annuity upon—"],[1,"(A) the earlier of—"],[2,"(i) a rollover of all or a portion of the amount to another individual retirement account or annuity; or"],[2,"(ii) one year after the transfer is made; or"],[1,"(B) a transfer that is made in a manner consistent with guidance provided by the Secretary."],[0,"(4)(A) In any case in which a qualified change in investment options occurs in connection with an individual account plan, a participant or beneficiary shall not be treated for purposes of paragraph (1) as not exercising control over the assets in his account in connection with such change if the requirements of subparagraph (C) are met in connection with such change."],[0,"(B) For purposes of subparagraph (A), the term \"qualified change in investment options\" means, in connection with an individual account plan, a change in the investment options offered to the participant or beneficiary under the terms of the plan, under which—"],[1,"(i) the account of the participant or beneficiary is reallocated among one or more remaining or new investment options which are offered in lieu of one or more investment options offered immediately prior to the effective date of the change, and"],[1,"(ii) the stated characteristics of the remaining or new investment options provided under clause (i), including characteristics relating to risk and rate of return, are, as of immediately after the change, reasonably similar to those of the existing investment options as of immediately before the change."],[0,"(C) The requirements of this subparagraph are met in connection with a qualified change in investment options if—"],[1,"(i) at least 30 days and no more than 60 days prior to the effective date of the change, the plan administrator furnishes written notice of the change to the participants and beneficiaries, including information comparing the existing and new investment options and an explanation that, in the absence of affirmative investment instructions from the participant or beneficiary to the contrary, the account of the participant or beneficiary will be invested in the manner described in subparagraph (B),"],[1,"(ii) the participant or beneficiary has not provided to the plan administrator, in advance of the effective date of the change, affirmative investment instructions contrary to the change, and"],[1,"(iii) the investments under the plan of the participant or beneficiary as in effect immediately prior to the effective date of the change were the product of the exercise by such participant or beneficiary of control over the assets of the account within the meaning of paragraph (1)."],[0,"(5) Default investment arrangements.—"],[1,"(A) In general.—For purposes of paragraph (1), a participant or beneficiary in an individual account plan meeting the notice requirements of subparagraph (B) shall be treated as exercising control over the assets in the account with respect to the amount of contributions and earnings which, in the absence of an investment election by the participant or beneficiary, are invested by the plan in accordance with regulations prescribed by the Secretary. The regulations under this subparagraph shall provide guidance on the appropriateness of designating default investments that include a mix of asset classes consistent with capital preservation or long-term capital appreciation, or a blend of both."],[1,"(B) Notice requirements.—"],[2,"(i) In general.—The requirements of this subparagraph are met if each participant or beneficiary—"],[3,"(I) receives, within a reasonable period of time before each plan year, a notice explaining the employee's right under the plan to designate how contributions and earnings will be invested and explaining how, in the absence of any investment election by the participant or beneficiary, such contributions and earnings will be invested, and"],[3,"(II) has a reasonable period of time after receipt of such notice and before the beginning of the plan year to make such designation."],[2,"(ii) Form of notice.—The requirements of clauses (i) and (ii) of section 401(k)(12)(D) of title 26 shall apply with respect to the notices described in this subparagraph."],[0,"(6) Default investment arrangements for a pension-linked emergency savings account.—For purposes of paragraph (1), a participant in a pension-linked emergency savings account shall be treated as exercising control over the assets in the account with respect to the amount of contributions and earnings which are invested in accordance with section 1193(c)(1)(A)(iii) of this title."],[0,"(d) Plan terminations"],[0,"(1) If, in connection with the termination of a pension plan which is a single-employer plan, there is an election to establish or maintain a qualified replacement plan, or to increase benefits, as provided under section 4980(d) of title 26, a fiduciary shall discharge the fiduciary's duties under this subchapter and subchapter III in accordance with the following requirements:"],[1,"(A) In the case of a fiduciary of the terminated plan, any requirement—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1104?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1104. Fiduciary duties","tname":"Labor","by":{"0":"18, 18, 18, 9, 28"}},{"t":"usc","label":"29 U.S.C. § 1108","url":"https://www.law.cornell.edu/uscode/text/29/1108","subs":["(c)"],"by":{"0":"9, 28"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)(1)(B)"],"stext":{"head":"§1132. Civil enforcement","paras":[[0,"(a) Persons empowered to bring a civil action"],[0,"A civil action may be brought—"],[1,"(1) by a participant or beneficiary—"],[2,"(A) for the relief provided for in subsection (c) of this section, or"],[2,"(B) to recover benefits due to him under the terms of his plan, to enforce his rights under the terms of the plan, or to clarify his rights to future benefits under the terms of the plan;"],[1,"(2) by the Secretary, or by a participant, beneficiary or fiduciary for appropriate relief under section 1109 of this title;"],[1,"(3) by a participant, beneficiary, or fiduciary (A) to enjoin any act or practice which violates any provision of this subchapter or the terms of the plan, or (B) to obtain other appropriate equitable relief (i) to redress such violations or (ii) to enforce any provisions of this subchapter or the terms of the plan;"],[1,"(4) by the Secretary, or by a participant, or beneficiary for appropriate relief in the case of a violation of section 1025(c) or 1032(a) of this title;"],[1,"(5) except as otherwise provided in subsection (b), by the Secretary (A) to enjoin any act or practice which violates any provision of this subchapter, or (B) to obtain other appropriate equitable relief (i) to redress such violation or (ii) to enforce any provision of this subchapter;"],[1,"(6) by the Secretary to collect any civil penalty under paragraph (2), (4), (5), (6), (7), (8), or (9) of subsection (c) or under subsection (i) or (l);"],[1,"(7) by a State to enforce compliance with a qualified medical child support order (as defined in section 1169(a)(2)(A) of this title);"],[1,"(8) by the Secretary, or by an employer or other person referred to in section 1021(f)(1) of this title, (A) to enjoin any act or practice which violates subsection (f) of section 1021 of this title, or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection;"],[1,"(9) in the event that the purchase of an insurance contract or insurance annuity in connection with termination of an individual's status as a participant covered under a pension plan with respect to all or any portion of the participant's pension benefit under such plan constitutes a violation of part 4 of this title 1 or the terms of the plan, by the Secretary, by any individual who was a participant or beneficiary at the time of the alleged violation, or by a fiduciary, to obtain appropriate relief, including the posting of security if necessary, to assure receipt by the participant or beneficiary of the amounts provided or to be provided by such insurance contract or annuity, plus reasonable prejudgment interest on such amounts;"],[1,"(10) in the case of a multiemployer plan that has been certified by the actuary to be in endangered or critical status under section 1085 of this title, if the plan sponsor—"],[2,"(A) has not adopted a funding improvement or rehabilitation plan under that section by the deadline established in such section, or"],[2,"(B) fails to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section,"],[1,"by an employer that has an obligation to contribute with respect to the multiemployer plan or an employee organization that represents active participants in the multiemployer plan, for an order compelling the plan sponsor to adopt a funding improvement or rehabilitation plan or to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section and the funding improvement or rehabilitation plan; or"],[1,"(11) in the case of a multiemployer plan, by an employee representative, or any employer that has an obligation to contribute to the plan, (A) to enjoin any act or practice which violates subsection (k) of section 1021 of this title (or, in the case of an employer, subsection (l) of such section), or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection."],[0,"(b) Plans qualified under Internal Revenue Code; maintenance of actions involving delinquent contributions"],[0,"(1) In the case of a plan which is qualified under section 401(a), 403(a), or 405(a) 2 of title 26 (or with respect to which an application to so qualify has been filed and has not been finally determined) the Secretary may exercise his authority under subsection (a)(5) with respect to a violation of, or the enforcement of, parts 2 and 3 of this subtitle (relating to participation, vesting, and funding), only if—"],[1,"(A) requested by the Secretary of the Treasury, or"],[1,"(B) one or more participants, beneficiaries, or fiduciaries, of such plan request in writing (in such manner as the Secretary shall prescribe by regulation) that he exercise such authority on their behalf. In the case of such a request under this paragraph he may exercise such authority only if he determines that such violation affects, or such enforcement is necessary to protect, claims of participants or beneficiaries to benefits under the plan."],[0,"(2) The Secretary shall not initiate an action to enforce section 1145 of this title."],[0,"(3) Except as provided in subsections (c)(9) and (a)(6) (with respect to collecting civil penalties under subsection (c)(9)), the Secretary is not authorized to enforce under this part any requirement of part 7 against a health insurance issuer offering health insurance coverage in connection with a group health plan (as defined in section 1191b(a)(1) of this title). Nothing in this paragraph shall affect the authority of the Secretary to issue regulations to carry out such part."],[0,"(c) Administrator's refusal to supply requested information; penalty for failure to provide annual report in complete form"],[0,"(1) Any administrator (A) who fails to meet the requirements of paragraph (1) or (4) of section 1166 2 of this title, section 1021(e)(1) of this title, section 1021(f) of this title,,3 section 1025(a) of this title, or section 1032(a) of this title with respect to a participant or beneficiary, or (B) who fails or refuses to comply with a request for any information which such administrator is required by this subchapter to furnish to a participant or beneficiary (unless such failure or refusal results from matters reasonably beyond the control of the administrator) by mailing the material requested to the last known address of the requesting participant or beneficiary within 30 days after such request may in the court's discretion be personally liable to such participant or beneficiary in the amount of up to $100 a day from the date of such failure or refusal, and the court may in its discretion order such other relief as it deems proper. For purposes of this paragraph, each violation described in subparagraph (A) with respect to any single participant, and each violation described in subparagraph (B) with respect to any single participant or beneficiary, shall be treated as a separate violation."],[0,"(2) The Secretary may assess a civil penalty against any plan administrator of up to $1,000 a day from the date of such plan administrator's failure or refusal to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title. For purposes of this paragraph, an annual report that has been rejected under section 1024(a)(4) of this title for failure to provide material information shall not be treated as having been filed with the Secretary."],[0,"(3) Any employer maintaining a plan who fails to meet the notice requirement of section 1021(d) of this title with respect to any participant or beneficiary or who fails to meet the requirements of section 1021(e)(2) of this title with respect to any person or who fails to meet the requirements of section 1082(d)(12)(E) 2 of this title with respect to any person may in the court's discretion be liable to such participant or beneficiary or to such person in the amount of up to $100 a day from the date of such failure, and the court may in its discretion order such other relief as it deems proper."],[0,"(4) The Secretary may assess a civil penalty of not more than $1,000 a day for each violation by any person of subsection (j), (k), or (l) of section 1021 of this title or section 1144(e)(3) of this title."],[0,"(5) The Secretary may assess a civil penalty against any person of up to $1,000 a day from the date of the person's failure or refusal to file the information required to be filed by such person with the Secretary under regulations prescribed pursuant to section 1021(g) of this title."],[0,"(6) If, within 30 days of a request by the Secretary to a plan administrator for documents under section 1024(a)(6) of this title, the plan administrator fails to furnish the material requested to the Secretary, the Secretary may assess a civil penalty against the plan administrator of up to $100 a day from the date of such failure (but in no event in excess of $1,000 per request). No penalty shall be imposed under this paragraph for any failure resulting from matters reasonably beyond the control of the plan administrator."],[0,"(7) The Secretary may assess a civil penalty against a plan administrator of up to $100 a day from the date of the plan administrator's failure or refusal to provide notice to participants and beneficiaries in accordance with subsection (i) or (m) of section 1021 of this title. For purposes of this paragraph, each violation with respect to any single participant or beneficiary shall be treated as a separate violation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1132?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1132. Civil enforcement","tname":"Labor","by":{"0":"28"}},{"t":"usc","label":"29 U.S.C. § 1136","url":"https://www.law.cornell.edu/uscode/text/29/1136","subs":["(b)"],"by":{"0":"21"}},{"t":"usc","label":"29 U.S.C. § 1144","url":"https://www.law.cornell.edu/uscode/text/29/1144","subs":["(a)"],"stext":{"head":"§1144. Other laws","paras":[[0,"(a) Supersedure; effective date"],[0,"Except as provided in subsection (b) of this section, the provisions of this subchapter and subchapter III shall supersede any and all State laws insofar as they may now or hereafter relate to any employee benefit plan described in section 1003(a) of this title and not exempt under section 1003(b) of this title. This section shall take effect on January 1, 1975."],[0,"(b) Construction and application"],[0,"(1) This section shall not apply with respect to any cause of action which arose, or any act or omission which occurred, before January 1, 1975."],[0,"(2)(A) Except as provided in subparagraph (B), nothing in this subchapter shall be construed to exempt or relieve any person from any law of any State which regulates insurance, banking, or securities."],[0,"(B) Neither an employee benefit plan described in section 1003(a) of this title, which is not exempt under section 1003(b) of this title (other than a plan established primarily for the purpose of providing death benefits), nor any trust established under such a plan, shall be deemed to be an insurance company or other insurer, bank, trust company, or investment company or to be engaged in the business of insurance or banking for purposes of any law of any State purporting to regulate insurance companies, insurance contracts, banks, trust companies, or investment companies."],[0,"(3) Nothing in this section shall be construed to prohibit use by the Secretary of services or facilities of a State agency as permitted under section 1136 of this title."],[0,"(4) Subsection (a) shall not apply to any generally applicable criminal law of a State."],[0,"(5)(A) Except as provided in subparagraph (B), subsection (a) shall not apply to the Hawaii Prepaid Health Care Act (Haw. Rev. Stat. §§393–1 through 393–51)."],[0,"(B) Nothing in subparagraph (A) shall be construed to exempt from subsection (a)—"],[1,"(i) any State tax law relating to employee benefit plans, or"],[1,"(ii) any amendment of the Hawaii Prepaid Health Care Act enacted after September 2, 1974, to the extent it provides for more than the effective administration of such Act as in effect on such date."],[0,"(C) Notwithstanding subparagraph (A), parts 1 and 4 of this subtitle, and the preceding sections of this part to the extent they govern matters which are governed by the provisions of such parts 1 and 4, shall supersede the Hawaii Prepaid Health Care Act (as in effect on or after January 14, 1983), but the Secretary may enter into cooperative arrangements under this paragraph and section 1136 of this title with officials of the State of Hawaii to assist them in effectuating the policies of provisions of such Act which are superseded by such parts 1 and 4 and the preceding sections of this part."],[0,"(6)(A) Notwithstanding any other provision of this section—"],[1,"(i) in the case of an employee welfare benefit plan which is a multiple employer welfare arrangement and is fully insured (or which is a multiple employer welfare arrangement subject to an exemption under subparagraph (B)), any law of any State which regulates insurance may apply to such arrangement to the extent that such law provides—"],[2,"(I) standards, requiring the maintenance of specified levels of reserves and specified levels of contributions, which any such plan, or any trust established under such a plan, must meet in order to be considered under such law able to pay benefits in full when due, and"],[2,"(II) provisions to enforce such standards, and"],[1,"(ii) in the case of any other employee welfare benefit plan which is a multiple employer welfare arrangement, in addition to this subchapter, any law of any State which regulates insurance may apply to the extent not inconsistent with the preceding sections of this subchapter."],[0,"(B) The Secretary may, under regulations which may be prescribed by the Secretary, exempt from subparagraph (A)(ii), individually or by class, multiple employer welfare arrangements which are not fully insured. Any such exemption may be granted with respect to any arrangement or class of arrangements only if such arrangement or each arrangement which is a member of such class meets the requirements of section 1002(1) and section 1003 of this title necessary to be considered an employee welfare benefit plan to which this subchapter applies."],[0,"(C) Nothing in subparagraph (A) shall affect the manner or extent to which the provisions of this subchapter apply to an employee welfare benefit plan which is not a multiple employer welfare arrangement and which is a plan, fund, or program participating in, subscribing to, or otherwise using a multiple employer welfare arrangement to fund or administer benefits to such plan's participants and beneficiaries."],[0,"(D) For purposes of this paragraph, a multiple employer welfare arrangement shall be considered fully insured only if the terms of the arrangement provide for benefits the amount of all of which the Secretary determines are guaranteed under a contract, or policy of insurance, issued by an insurance company, insurance service, or insurance organization, qualified to conduct business in a State."],[0,"(7) Subsection (a) shall not apply to qualified domestic relations orders (within the meaning of section 1056(d)(3)(B)(i) of this title), qualified medical child support orders (within the meaning of section 1169(a)(2)(A) of this title), and the provisions of law referred to in section 1169(a)(2)(B)(ii) of this title to the extent they apply to qualified medical child support orders."],[0,"(8) Subsection (a) of this section shall not be construed to preclude any State cause of action—"],[1,"(A) with respect to which the State exercises its acquired rights under section 1169(b)(3) of this title with respect to a group health plan (as defined in section 1167(1) of this title), or"],[1,"(B) for recoupment of payment with respect to items or services pursuant to a State plan for medical assistance approved under title XIX of the Social Security Act [42 U.S.C. 1396 et seq.] which would not have been payable if such acquired rights had been executed before payment with respect to such items or services by the group health plan."],[0,"(9) For additional provisions relating to group health plans, see section 1191 of this title."],[0,"(c) Definitions"],[0,"For purposes of this section:"],[1,"(1) The term \"State law\" includes all laws, decisions, rules, regulations, or other State action having the effect of law, of any State. A law of the United States applicable only to the District of Columbia shall be treated as a State law rather than a law of the United States."],[1,"(2) The term \"State\" includes a State, any political subdivisions thereof, or any agency or instrumentality of either, which purports to regulate, directly or indirectly, the terms and conditions of employee benefit plans covered by this subchapter."],[0,"(d) Alteration, amendment, modification, invalidation, impairment, or supersedure of any law of the United States prohibited"],[0,"Nothing in this subchapter shall be construed to alter, amend, modify, invalidate, impair, or supersede any law of the United States (except as provided in sections 1031 and 1137(b) of this title) or any rule or regulation issued under any such law."],[0,"(e) Automatic contribution arrangements"],[0,"(1) Notwithstanding any other provision of this section, this subchapter shall supersede any law of a State which would directly or indirectly prohibit or restrict the inclusion in any plan of an automatic contribution arrangement. The Secretary may prescribe regulations which would establish minimum standards that such an arrangement would be required to satisfy in order for this subsection to apply in the case of such arrangement."],[0,"(2) For purposes of this subsection, the term \"automatic contribution arrangement\" means an arrangement—"],[1,"(A) under which a participant may elect to have the plan sponsor make payments as contributions under the plan on behalf of the participant, or to the participant directly in cash,"],[1,"(B) under which a participant is treated as having elected to have the plan sponsor make such contributions in an amount equal to a uniform percentage of compensation provided under the plan until the participant specifically elects not to have such contributions made (or specifically elects to have such contributions made at a different percentage), and"],[1,"(C) under which such contributions are invested in accordance with regulations prescribed by the Secretary under section 1104(c)(5) of this title."],[0,"(3)(A) The plan administrator of an automatic contribution arrangement shall, within a reasonable period before such plan year, provide to each participant to whom the arrangement applies for such plan year notice of the participant's rights and obligations under the arrangement which—"],[1,"(i) is sufficiently accurate and comprehensive to apprise the participant of such rights and obligations, and"],[1,"(ii) is written in a manner calculated to be understood by the average participant to whom the arrangement applies."],[0,"(B) A notice shall not be treated as meeting the requirements of subparagraph (A) with respect to a participant unless—"],[1,"(i) the notice includes an explanation of the participant's right under the arrangement not to have elective contributions made on the participant's behalf (or to elect to have such contributions made at a different percentage),"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1144?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1144. Other laws","tname":"Labor","by":{"0":"21, 3, 13"}},{"t":"usc","label":"29 U.S.C. § 1185","url":"https://www.law.cornell.edu/uscode/text/29/1185","subs":["(b)(4)"],"by":{"0":"19"}},{"t":"usc","label":"9 U.S.C. § 1191b","url":"https://www.law.cornell.edu/uscode/text/9/1191b","subs":["(a)(1)"],"by":{"0":"19"}},{"t":"usc","label":"29 U.S.C. § 1191b","url":"https://www.law.cornell.edu/uscode/text/29/1191b","subs":["(a)(2)"],"by":{"0":"19"}},{"t":"usc","label":"15 U.S.C. § 1012","url":"https://www.law.cornell.edu/uscode/text/15/1012","by":{"0":"12"}},{"t":"law","label":"Pub. L. No. 104-204","url":"https://www.govinfo.gov/link/plaw/104/public/204","by":{"0":"19"}},{"t":"usc","label":"42 U.S.C. § 300e","url":"https://www.law.cornell.edu/uscode/text/42/300e","stext":{"head":"§300e. Requirements of health maintenance organizations","paras":[[0,"(a) \"Health maintenance organization\" defined"],[0,"For purposes of this subchapter, the term \"health maintenance organization\" means a public or private entity which is organized under the laws of any State and which (1) provides basic and supplemental health services to its members in the manner prescribed by subsection (b), and (2) is organized and operated in the manner prescribed by subsection (c)."],[0,"(b) Manner of supplying basic and supplemental health services to members"],[0,"A health maintenance organization shall provide, without limitations as to time or cost other than those prescribed by or under this subchapter, basic and supplemental health services to its members in the following manner:"],[1,"(1) Each member is to be provided basic health services for a basic health services payment which (A) is to be paid on a periodic basis without regard to the dates health services (within the basic health services) are provided; (B) is fixed without regard to the frequency, extent, or kind of health service (within the basic health services) actually furnished; (C) except in the case of basic health services provided a member who is a full-time student (as defined by the Secretary) at an accredited institution of higher education, is fixed under a community rating system; and (D) may be supplemented by additional nominal payments which may be required for the provision of specific services (within the basic health services), except that such payments may not be required where or in such a manner that they serve (as determined under regulations of the Secretary) as a barrier to the delivery of health services. Such additional nominal payments shall be fixed in accordance with the regulations of the Secretary. If a health maintenance organization offers to its members the opportunity to obtain basic health services through a physician not described in subsection (b)(3)(A), the organization may require, in addition to payments described in clause (D) of this paragraph, a reasonable deductible to be paid by a member when obtaining a basic health service from such a physician. A health maintenance organization may include a health service, defined as a supplemental health service by section 300e–1(2) of this title, in the basic health services provided its members for a basic health services payment described in the first sentence. In the case of an entity which before it became a qualified health maintenance organization (within the meaning of section 300e–9(d) 1 of this title) provided comprehensive health services on a prepaid basis, the requirement of clause (C) shall not apply to such entity until the expiration of the forty-eight month period beginning with the month following the month in which the entity became such a qualified health organization. The requirements of this paragraph respecting the basic health services payment shall not apply to the provision of basic health services to a member for an illness or injury for which the member is entitled to benefits under a workmen's compensation law or an insurance policy but only to the extent such benefits apply to such services. For the provision of such services for an illness or injury for which a member is entitled to benefits under such a law, the health maintenance organization may, if authorized by such law, charge or authorize the provider of such services to charge, in accordance with the charges allowed under such law, the insurance carrier, employer, or other entity which under such law is to pay for the provision of such services or, to the extent that such member has been paid under such law for such services, such member. For the provision of such services for an illness or injury for which a member is entitled to benefits under an insurance policy, a health maintenance organization may charge or authorize the provider of such services to charge the insurance carrier under such policy or, to the extent that such member has been paid under such policy for such services, such member."],[1,"(2) For such payment or payments (hereinafter in this subchapter referred to as \"supplemental health services payments\") as the health maintenance organization may require in addition to the basic health services payment, the organization may provide to each of its members any of the health services which are included in supplemental health services (as defined in section 300e–1(2) of this title). Supplemental health services payments which are fixed on a prepayment basis shall be fixed under a community rating system unless the supplemental health services payment is for a supplemental health service provided a member who is a full-time student (as defined by the Secretary) at an accredited institution of higher education, except that, in the case of an entity which before it became a qualified health maintenance organization (within the meaning of section 300e–9(d) 1 of this title) provided comprehensive health services on a prepaid basis, the requirement of this sentence shall not apply to such entity during the forty-eight month period beginning with the month following the month in which the entity became such a qualified health maintenance organization."],[1,"(3)(A) Except as provided in subparagraph (B), at least 90 percent of the services of a physician which are provided as basic health services shall be provided through—"],[2,"(i) members of the staff of the health maintenance organization,"],[2,"(ii) a medical group (or groups),"],[2,"(iii) an individual practice association (or associations),"],[2,"(iv) physicians or other health professionals who have contracted with the health maintenance organization for the provision of such services, or"],[2,"(v) any combination of such staff, medical group (or groups), individual practice association (or associations) or physicians or other health professionals under contract with the organization."],[1,"(B) Subparagraph (A) does not apply to the provision of the services of a physician—"],[2,"(i) which the health maintenance organization determines, in conformity with regulations of the Secretary, are unusual or infrequently used, or"],[2,"(ii) which are provided a member of the organization in a manner other than that prescribed by subparagraph (A) because of an emergency which made it medically necessary that the service be provided to the member before it could be provided in a manner prescribed by subparagraph (A)."],[1,"(C) Contracts between a health maintenance organization and health professionals for the provision of basic and supplemental health services shall include such provisions as the Secretary may require, but only to the extent that such requirements are designed to insure the delivery of quality health care services and sound fiscal management."],[1,"(D) For purposes of this paragraph the term \"health professional\" means physicians, dentists, nurses, podiatrists, optometrists, and such other individuals engaged in the delivery of health services as the Secretary may by regulation designate."],[1,"(4) Basic health services (and only such supplemental health services as members have contracted for) shall within the area served by the health maintenance organization be available and accessible to each of its members with reasonable promptness and in a manner which assures continuity, and when medically necessary be available and accessible twenty-four hours a day and seven days a week, except that a health maintenance organization which has a service area located wholly in a nonmetropolitan area may make a basic health service available outside its service area if that basic health service is not a primary care or emergency health care service and if there is an insufficient number of providers of that basic health service within the service area who will provide such service to members of the health maintenance organization. A member of a health maintenance organization shall be reimbursed by the organization for his expenses in securing basic and supplemental health services other than through the organization if the services were medically necessary and immediately required because of an unforeseen illness, injury, or condition."],[1,"(5) To the extent that a natural disaster, war, riot, civil insurrection, or any other similar event not within the control of a health maintenance organization (as determined under regulations of the Secretary) results in the facilities, personnel, or financial resources of a health maintenance organization not being available to provide or arrange for the provision of a basic or supplemental health service in accordance with the requirements of paragraphs (1) through (4) of this subsection, such requirements only require the organization to make a good-faith effort to provide or arrange for the provision of such service within such limitation on its facilities, personnel, or resources."],[1,"(6) A health maintenance organization that otherwise meets the requirements of this subchapter may offer a high-deductible health plan (as defined in section 220(c)(2) of title 26)."],[0,"(c) Organizational requirements"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300e?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§300e. Requirements of health maintenance organizations","tname":"The Public Health and Welfare","by":{"0":"23"}},{"t":"usc","label":"29 U.S.C. § 1185b","url":"https://www.law.cornell.edu/uscode/text/29/1185b","subs":["(a)","(c)(2)"],"by":{"0":"19, 19"}},{"t":"usc","label":"42 U.S.C. § 1395w-22","url":"https://www.law.cornell.edu/uscode/text/42/1395w-22","subs":["(j)(4)"],"by":{"0":"20"}},{"t":"usc","label":"42 U.S.C. § 1396b","url":"https://www.law.cornell.edu/uscode/text/42/1396b","subs":["(m)(2)(A)(x)"],"by":{"0":"20"}},{"t":"reg","label":"42 C.F.R. § 434.70","url":"https://www.ecfr.gov/current/title-42/section-434.70","subs":["(a)(2)"],"by":{"0":"20"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(6)"],"by":{"0":"17"}}]};